import com.albion.market.litert.IslandEngine
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

private val nil=JSONObject.NULL
private fun crop(id:String, plots:Int?=null, slots:Int?=null, watered:Int?=0)=JSONObject().put("crop_id",id).put("plot_count",plots?:nil).put("slot_count",slots?:nil).put("watered_slots",watered?:nil)
private fun island(id:String="i1",city:String?="Martlock",plots:Int?=null,occupied:Int?=null,occupiedSlots:Int?=null,available:Int?=null,crops:JSONArray?=null)=JSONObject()
 .put("id",id).put("island_city",city?:nil).put("plot_count",plots?:nil).put("occupied_plots",occupied?:nil).put("occupied_slots",occupiedSlots?:nil)
 .put("available_slots",available?:nil).put("crop_allocations",crops?:nil).put("animal_allocations",nil)
private fun request(vararg islands:JSONObject)=JSONObject().put("islands",JSONArray(islands.toList()))
fun main() {
 val catalog=JSONObject(File("assets/island/farmables.json").readText())
 val wheat="T3_FARM_WHEAT_SEED";val carrot="T1_FARM_CARROT_SEED";val cabbage="T5_FARM_CABBAGE_SEED"
 fun run(r:JSONObject)=IslandEngine.execute(r,catalog,null){false}
 val eight=run(request(island(plots=8,occupied=0,crops=JSONArray().put(crop(wheat,plots=8)))))
 check(eight.getString("status")=="partial" && eight.getInt("total_plantations")==72 && eight.getInt("seeds_first_cycle")==72)
 check(eight.getJSONArray("islands").getJSONObject(0).getInt("available_farm_slots")==72)
 check(eight.isNull("economic_profit") && !eight.getBoolean("ranking_available"))
 val occupied=run(request(island(plots=8,occupied=2)))
 check(occupied.getJSONArray("islands").getJSONObject(0).getInt("available_farm_slots")==54)
 check(occupied.isNull("total_plantations") && occupied.isNull("seeds_first_cycle"))
 val mixed=run(request(island(plots=8,occupied=0,crops=JSONArray().put(crop(wheat,plots=4)).put(crop(cabbage,plots=4)))))
 check(mixed.getInt("total_plantations")==72)
 val m=mixed.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations")
 check(m.getJSONObject(0).getInt("plantations")==36 && m.getJSONObject(1).getInt("plantations")==36)
 val slots=run(request(island(available=8,crops=JSONArray().put(crop(carrot,slots=8)))))
 check(slots.getInt("total_plantations")==8 && slots.getInt("total_available_farm_slots")==8)
 val multi=run(request(island("a","Thetford",5,0,crops=JSONArray().put(crop(wheat,plots=5))),island("b","Martlock",7,0,crops=JSONArray().put(crop(carrot,plots=7)))))
 check(multi.getInt("total_plantations")==108 && multi.getInt("total_available_farm_slots")==108)
 val partial=run(request(island(plots=3,occupied=1,occupiedSlots=4,crops=JSONArray().put(crop(wheat,slots=14)))))
 check(partial.getInt("total_available_farm_slots")==14)
 check(run(request(island(plots=2,occupied=1,crops=JSONArray().put(crop(wheat,plots=2))))).getJSONObject("error").getString("code")=="INSUFFICIENT_CAPACITY")
 check(run(request(island(plots=1,occupied=0,crops=JSONArray().put(crop("T2_FARM_AGARIC_SEED",plots=1))))).getJSONObject("error").getString("code")=="UNKNOWN_CROP")
 check(run(request(island(plots=1,occupied=0,crops=JSONArray().put(crop(wheat,plots=1,watered=10))))).getJSONObject("error").getString("code")=="INVALID_ARGUMENT")
 val unspecified=run(request(island(plots=8,crops=JSONArray().put(crop(wheat,plots=8)))))
 check(unspecified.isNull("total_available_farm_slots") && unspecified.getString("status")=="partial")
 check(IslandEngine.execute(request(island(plots=1,occupied=0)),catalog,null){true}.getJSONObject("error").getString("code")=="CANCELLED")
 // Everything below is synthetic, in-memory, and exclusively used by this test.
 val verified=JSONObject(catalog.toString()).put("economics_facts",JSONObject().put("entries",JSONArray().put(JSONObject()
  .put("status","verified").put("crop_id",cabbage).put("island_city","Martlock").put("sale_city","Martlock")
  .put("premium",true).put("specialization_level",0).put("output_item_id","T5_CABBAGE")
  .put("provenance",JSONObject().put("source","synthetic test").put("revision","test"))
  .put("harvestPerSlot",9).put("cityYieldMultiplier",1.1).put("saleTaxRate",0).put("saleFeePerCycle",0)
  .put("seedReturnWithoutFocus",.8).put("seedReturnWithFocus",1.2).put("focusPerWateredSlot",100).put("cycleDays",1))))
 val npcEntry=JSONObject().put("itemId",cabbage).put("status","verified").put("currency","silver").put("transaction","player_buys_from_farming_merchant")
  .put("value",10000).put("server","americas").put("source","synthetic test").put("verifiedAt","test")
 verified.put("npc_prices",JSONObject().put("entries",JSONArray().put(npcEntry)))
 val market=JSONObject().put("snapshots",JSONArray().put(JSONObject().put("status","ok").put("server","americas").put("results",JSONArray()
  .put(JSONObject().put("status","ok").put("server","americas").put("city","Martlock").put("quality",1).put("item_id","T5_CABBAGE").put("average",439.68))
  .put(JSONObject().put("status","ok").put("server","americas").put("city","Martlock").put("quality",1).put("item_id",cabbage).put("average",20000)))))
 val allocation=crop(cabbage,plots=1,watered=5).put("owned_seeds",0)
 val economicRequest=request(island(plots=1,occupied=0,crops=JSONArray().put(allocation)))
  .put("server","americas").put("premium",true).put("sale_cities",JSONArray().put("Martlock"))
  .put("specializations",JSONArray().put(JSONObject().put("item_id",cabbage).put("level",0))).put("budget_silver",80000)
 fun economic(req:JSONObject,cat:JSONObject=verified,snap:JSONObject?=market):JSONObject=IslandEngine.execute(req,cat,snap){false}
 fun row(r:JSONObject)=r.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations").getJSONObject(0)
 val npcDefault=economic(economicRequest);val econ=row(npcDefault).getJSONObject("economics_mean_flow")
 check(row(npcDefault).getString("purchase_source")=="npc")
 check(row(npcDefault).getDouble("seed_unit_price")==10000.0)
 check(kotlin.math.abs(econ.getJSONObject("baseline").getDouble("meanFlowProfitPerCycle")-21175.488)<1e-6)
 check(kotlin.math.abs(econ.getJSONObject("selected").getDouble("meanFlowSurplusSeeds")-.2)<1e-6)
 check(npcDefault.getString("budget_check")=="estimated_seed_cost_exceeds_budget")
 val missingNpc=JSONObject(verified.toString()).put("npc_prices",JSONObject().put("entries",JSONArray()))
 val missingNpcResult=economic(economicRequest,missingNpc)
 check(row(missingNpcResult).isNull("seed_unit_price") && row(missingNpcResult).isNull("economics_mean_flow"))
 check(missingNpcResult.getString("budget_check")=="incomplete_seed_cost")
 val manualMarket=JSONObject(economicRequest.toString())
 manualMarket.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations").getJSONObject(0).put("purchase_source","market").put("purchase_city","Martlock")
 val marketResult=economic(manualMarket)
 check(row(marketResult).getString("purchase_source")=="market" && row(marketResult).getDouble("seed_unit_price")==20000.0)
 check(row(marketResult).getJSONObject("economics_mean_flow").getJSONObject("initialSeeds").getDouble("purchaseCash")==180000.0)
 val marketUnavailable=economic(manualMarket,verified,null)
 check(row(marketUnavailable).isNull("seed_unit_price") && row(marketUnavailable).isNull("economics_mean_flow"))
 val missingMarketCity=JSONObject(manualMarket.toString());missingMarketCity.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations").getJSONObject(0).put("purchase_city",JSONObject.NULL)
 check(row(economic(missingMarketCity)).isNull("seed_unit_price"))
 val unknownOwned=JSONObject(economicRequest.toString());unknownOwned.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations").getJSONObject(0).remove("owned_seeds")
 val unknownOwnedResult=economic(unknownOwned);check(row(unknownOwnedResult).isNull("initial_seed_cost") && row(unknownOwnedResult).getDouble("cost_if_all_seeds_purchased")==90000.0)
 check(unknownOwnedResult.isNull("initial_seed_cost_total") && unknownOwnedResult.getString("budget_check")=="incomplete_seed_cost")
 val untrustedFacts=JSONObject(verified.toString());untrustedFacts.remove("economics_facts");check(row(economic(economicRequest,untrustedFacts)).isNull("economics_mean_flow"))
 val injected=JSONObject(economicRequest.toString());injected.getJSONArray("islands").getJSONObject(0).getJSONArray("crop_allocations").getJSONObject(0).put("harvestPerSlot",999999).put("seedReturnWithoutFocus",999999)
 check(kotlin.math.abs(row(economic(injected)).getJSONObject("economics_mean_flow").getJSONObject("output").getDouble("meanUnitsPerCycle")-89.1)<1e-6)
 // Animal purchase input values are also synthetic. No farm capacity is assumed for animals.
 val chick="T3_FARM_CHICKEN_BABY"
 val animalCatalog=JSONObject(catalog.toString()).put("npc_prices",JSONObject().put("entries",JSONArray().put(JSONObject()
  .put("itemId",chick).put("category","domestic_young_animal").put("status","reference").put("currency","silver")
  .put("transaction","player_buys_from_farming_merchant").put("value",5000))))
 val animal=JSONObject().put("animal_id",chick).put("plot_count",nil).put("slot_count",3).put("purchase_source",nil).put("purchase_city",nil)
 val animalRequest=request(island(plots=1,occupied=0,crops=JSONArray()).put("animal_allocations",JSONArray().put(animal))).put("server","americas").put("budget_silver",100000)
 fun purchase(r:JSONObject)=r.getJSONArray("islands").getJSONObject(0).getJSONArray("animal_purchases").getJSONObject(0)
 val animalResult=economic(animalRequest,animalCatalog,null)
 check(purchase(animalResult).getString("purchase_source")=="npc" && purchase(animalResult).getLong("cost_if_all_animals_purchased")==15000L)
 check(purchase(animalResult).isNull("actual_purchase_cost") && animalResult.getString("status")=="partial")
 check(animalResult.getString("budget_check")=="estimated_seed_cost_within_budget_only")
 val noSlot=JSONObject(animalRequest.toString());noSlot.getJSONArray("islands").getJSONObject(0).getJSONArray("animal_allocations").getJSONObject(0).put("slot_count",nil).put("plot_count",1)
 check(purchase(economic(noSlot,animalCatalog,null)).isNull("cost_if_all_animals_purchased"))
 val noNpc=JSONObject(animalCatalog.toString()).put("npc_prices",JSONObject().put("entries",JSONArray()))
 check(purchase(economic(animalRequest,noNpc,market)).isNull("unit_price"))
 val marketAnimal=JSONObject(animalRequest.toString());marketAnimal.getJSONArray("islands").getJSONObject(0).getJSONArray("animal_allocations").getJSONObject(0).put("purchase_source","market").put("purchase_city","Martlock")
 check(purchase(economic(marketAnimal,animalCatalog,null)).isNull("unit_price"))
 val badAnimal=JSONObject(animalRequest.toString());badAnimal.getJSONArray("islands").getJSONObject(0).getJSONArray("animal_allocations").getJSONObject(0).put("animal_id","UNKNOWN_FAKE")
 check(economic(badAnimal,animalCatalog,null).getJSONObject("error").getString("code")=="UNKNOWN_ANIMAL")
 println("Island capacity: 8 plots/72 seeds, occupied plots, mixed crops, 8 slots, two islands, partial plots and cancellation passed")
}
